SELECT

FROM record_access_audit a

WHERE a.id = #{id}

SELECT

FROM record_access_audit a

WHERE a.id > 0
    AND a.del_flag = #{DEL_FLAG_NORMAL}
    AND a.company_id = #{companyId}

        AND a.patient_id = #{patientId}


        AND a.action = #{action}

ORDER BY a.create_date DESC, a.id DESC
LIMIT #{limit}
